import { useState } from 'react';
import axios from 'axios';

export default function AdminRegisterCard() {
  const [email, setEmail] = useState('');
  const [cardUID, setCardUID] = useState('');
  const [companyId] = useState('507f1f77bcf86cd799439011'); // Default test company ID
  const [statusMessage, setStatusMessage] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setStatusMessage(null);

    try {
      const response = await axios.post('http://localhost:5000/api/cards/register', {
        email,
        cardUID: cardUID.trim().toUpperCase(),
        companyId
      });

      setStatusMessage({ type: 'success', text: response.data.message });
      setEmail('');
      setCardUID('');
    } catch (error) {
      setStatusMessage({ 
        type: 'error', 
        text: error.response?.data?.message || 'Failed to link card' 
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto mt-10 p-6 bg-white rounded-xl shadow-md border border-gray-100">
      <h2 className="text-xl font-bold text-gray-800 mb-4">Link RFID Card to User</h2>
      
      {statusMessage && (
        <div className={`p-3 mb-4 rounded-lg text-sm ${statusMessage.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
          {statusMessage.text}
        </div>
      )}

      <form onSubmit={handleRegister} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Customer Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            placeholder="customer@example.com"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Card UID (Hex)</label>
          <input
            type="text"
            value={cardUID}
            onChange={(e) => setCardUID(e.target.value)}
            required
            placeholder="e.g. 4FFE207B"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 uppercase"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition duration-200 disabled:opacity-50"
        >
          {loading ? 'Linking Card...' : 'Register & Link Card'}
        </button>
      </form>
    </div>
  );
}
